[8862] = { en = "Elune's Candle", tier = 4,
  t = "De kaars van Elune",
  p = "De kaars van Elune is een voorwerp dat de volgelingen van het Lunar Festival diep vereren. In de kaars zit echt maanlicht, klaar om losgelaten te worden!$B$BDit licht is voor de meeste wezens onschadelijk, maar je zult merken dat Omen en zijn dienaren erdoor verbrand en verblind worden.",
  c = "Goed dan - ik aanvaard deze Coins of Ancestry. Neem de kaars van Elune met mijn zegen. Geniet ook van dit gratis vuurwerk.$b$bMoge je Lunar Festival vrolijk zijn en vol plezier, $n.$b$bEn als je besluit om Omen en zijn dienaren onder ogen te komen, zul je de kaars van Elune heel nuttig vinden...",
  g = { {"kaars", "candle"}, {"voorwerp", "object, artifact"}, {"volgelingen", "disciples, followers (volgeling)"}, {"vereren", "to revere"}, {"losgelaten", "released, unleashed (loslaten)"}, {"onschadelijk", "harmless"}, {"dienaren", "minions (dienaar)"}, {"verblind", "dazzled, blinded (verblinden)"}, {"aanvaard", "accept (aanvaarden)"}, {"zegen", "blessing"}, {"gratis", "free, complimentary"}, {"vuurwerk", "fireworks"}, {"Moge", "may (mogen)"}, {"onder ogen te komen", "to face (onder ogen komen)"} },
},

[8863] = { en = "Festival Dumplings", tier = 4,
  t = "Festivalknoedels",
  p = "Als je honger hebt, ben je hier aan het juiste adres, vriend!$B$BKnoedels zijn het traditionele eten van het Lunar Festival. Het wordt al geserveerd sinds het eerste Lunar Festival, en ik ben blij dat ik het op dit festival kan aanbieden. In ruil voor maar één Coin of Ancestry deel ik met je een proefje van een van de lekkerste gerechten die je ooit zult eten!",
  c = "Uitstekend - geniet van deze knoedels, met de complimenten van mij. Ze zijn maar een klein teken van waardering voor de eer die je jezelf met je daden hebt gebracht, maar ik denk dat je er toch van zult genieten.$B$BAls je nog meer Coins of Ancestry hebt, sta ik klaar om je in ruil een grote keuze aan spullen aan te bieden.",
  g = { {"knoedels", "dumplings (knoedel)"}, {"Festivalknoedels", "festival dumplings"}, {"aan het juiste adres", "in the right place"}, {"traditionele", "traditional (traditioneel)"}, {"geserveerd", "served (serveren)"}, {"aanbieden", "to offer"}, {"in ruil", "in exchange"}, {"proefje", "sample, taste"}, {"gerechten", "dishes (gerecht)"}, {"waardering", "appreciation"}, {"eer", "honour"}, {"daden", "deeds (daad)"}, {"sta ik klaar", "I stand ready (klaarstaan)"} },
},

[8864] = { en = "Festive Lunar Dresses", tier = 4,
  t = "Feestjurken voor het Lunar Festival",
  p = "Ik heb een selectie jurken die je misschien interessant vindt. Zulke jurken werden vroeger gedragen tijdens het Lunar Festival, en de selectie die ik vandaag heb, is misschien de mooiste die ik ooit heb gezien. Elke jurk is met de hand gemaakt, met alleen de beste en zachtste materialen.$B$BIn ruil voor wat Coins of Ancestry mag je een van de drie modellen kiezen om zelf te houden. Vind je dat goed?",
  c = "Goed dan - ik aanvaard deze Coins of Ancestry. Neem je jurk met mijn zegen. Geniet ook van dit gratis vuurwerk.$B$BJij hebt je ouderen geëerd, en jij eert mij met alleen al je aanwezigheid. Dank je, en moge je Lunar Festival vrolijk zijn.",
  g = { {"Feestjurken", "festive dresses (feestjurk)"}, {"selectie", "selection"}, {"gedragen", "worn (dragen)"}, {"zachtste", "softest (zacht)"}, {"materialen", "materials (materiaal)"}, {"in ruil voor", "in exchange for"}, {"modellen", "styles, models (model)"}, {"aanvaard", "accept (aanvaarden)"}, {"zegen", "blessing"}, {"gratis", "free, complimentary"}, {"vuurwerk", "fireworks"}, {"ouderen", "elders (oudere)"}, {"geëerd", "honoured (eren)"}, {"aanwezigheid", "presence"}, {"moge", "may (mogen)"} },
},

[9154] = { en = "Light's Hope Chapel", tier = 4,
  t = "Light's Hope Chapel",
  d = "De Scourge is teruggekeerd, in grotere aantallen dan we ooit eerder hebben gezien. De Argent Dawn zoekt alle mannen en vrouwen die bereid en in staat zijn om ons land te verdedigen.$b$b Als je onze zaak deelt, breng dit document dan naar de Keeper of the Rolls in Light's Hope Chapel in de Eastern Plaguelands.",
  o = "Breng de Call to Arms Announcement naar de Keeper of the Rolls in Light's Hope Chapel in de Eastern Plaguelands.",
  p = "Je komt je bij onze orde aansluiten, nietwaar?",
  c = "De Argent Dawn heeft om hulp gevraagd, en jij hebt, samen met anderen, gehoor gegeven. We hebben geen tijd om je te trainen. We vertrouwen op je vaardigheden, en erop dat je ons helpt om deze dreiging van de Scourge terug te slaan.",
  g = { {"teruggekeerd", "returned (terugkeren)"}, {"aantallen", "numbers (aantal)"}, {"bereid", "willing"}, {"in staat", "capable, able"}, {"verdedigen", "to defend"}, {"zaak", "cause"}, {"orde", "order (organisation)"}, {"nietwaar", "isn't it, haven't you"}, {"gehoor gegeven", "answered, responded (gehoor geven)"}, {"vaardigheden", "skills, abilities (vaardigheid)"}, {"dreiging", "threat"}, {"terug te slaan", "to throw back (terugslaan)"} },
},

[9247] = { en = "The Keeper's Call", tier = 4,
  t = "De oproep van de Keeper",
  d = "$N,$B$BIn het verleden heb je de belangen van de Argent Dawn gediend, altijd zo goed als je kon. Nu laten we opnieuw de klaroen klinken, in de tijd van onze grootste nood.$B$B$N, meld je alsjeblieft bij de Keeper of the Rolls in Light's Hope Chapel in de Eastern Plaguelands als je bereid bent om ons nog een keer te helpen.",
  o = "Breng de brief van de Keeper of the Rolls naar hem in Light's Hope Chapel in de Eastern Plaguelands.",
  g = { {"oproep", "call, summons"}, {"verleden", "past"}, {"belangen", "interests (belang)"}, {"gediend", "served (dienen)"}, {"klaroen", "clarion, trumpet"}, {"klinken", "to sound"}, {"nood", "need, distress"}, {"meld je", "report (zich melden)"}, {"bereid", "willing"} },
},

[9250] = { en = "Frame of Atiesh", tier = 4,
  t = "Het frame van Atiesh",
  d = "Nu het frame gevormd is, is Atiesh bijna heel. Alleen de kop en de voet van de staf ontbreken nog. Er is ook nog een klein probleem: de staf is een kanaal voor het kwaad van Sargeras.$B$BZoek iemand die je kan helpen om de laatste stukken te vinden en het kwaad uit de staf te verdrijven.",
  o = "Zoek iemand die je wil helpen om de laatste twee stukken van de staf terug te vinden en hem van het kwaad te bevrijden.",
  p = "Het was haar tijd, sterveling.",
  c = "De aartsmagiërs zijn gestorven.$B$BRouw niet om hun dood, $N. Al zulke dingen zijn voorbestemd. Net zoals het voorbestemd was dat jij de staf van de Guardian in handen zou hebben...",
  g = { {"gevormd", "formed (vormen)"}, {"heel", "whole"}, {"voet", "base, foot"}, {"staf", "staff"}, {"ontbreken", "are missing (ontbreken)"}, {"kanaal", "conduit, channel"}, {"kwaad", "evil"}, {"verdrijven", "to drive out, exorcise"}, {"bevrijden", "to free, rid"}, {"sterveling", "mortal"}, {"aartsmagiërs", "archmages (aartsmagiër)"}, {"Rouw", "mourn (rouwen)"}, {"voorbestemd", "fated, predestined"}, {"in handen", "in (one's) hands"} },
},

[9251] = { en = "Atiesh, the Befouled Greatstaff", tier = 4,
  t = "Atiesh, the Befouled Greatstaff",
  d = "Je vraagt je af waarom je nog leeft. Je hebt tenslotte een voorwerp van groot kwaad in je bezit. Het antwoord is niet duidelijk, $N. Ik doe alleen wat ik moet doen.$B$BKel'Thuzad zit op zijn troon in Naxxramas en smeedt plannen... Hij zoekt wat jij vasthoudt, en hij heeft wat jij zoekt.$B$BEn de voet van de staf: de dwerg Brann Bronzebeard had die bij zich toen hij Ahn'Qiraj binnenging. Hij heeft Ahn'Qiraj verlaten, maar de voet van Atiesh is daar gebleven.$B$BAls je erin slaagt om de stukken terug te halen, breng ze dan naar mij terug.",
  o = "Anachronos bij de Caverns of Time in Tanaris wil de Staff Head of Atiesh en de Base of Atiesh.",
  p = "In zijn huidige vorm is de staf veel te gevaarlijk om in de handen van een sterveling te zijn.",
  c = "Er zit een wezen in... een wezen dat niet van deze wereld is.",
  g = { {"Je vraagt je af", "you wonder (zich afvragen)"}, {"tenslotte", "after all"}, {"voorwerp", "object, item"}, {"kwaad", "evil"}, {"bezit", "possession"}, {"troon", "throne"}, {"smeedt plannen", "is plotting (plannen smeden)"}, {"vasthoudt", "hold (vasthouden)"}, {"voet", "base, foot"}, {"staf", "staff"}, {"erin slaagt", "succeed (erin slagen)"}, {"huidige", "current (huidig)"}, {"sterveling", "mortal"}, {"wezen", "being, creature"} },
},

[9257] = { en = "Atiesh, Greatstaff of the Guardian", tier = 4,
  t = "Atiesh, Greatstaff of the Guardian",
  d = "Deze laatste taak wordt de moeilijkste van allemaal, $N. Je hebt zowel een Old God als de generaal van de Lich King bevochten en verslagen, maar nu moet je de hand van Sargeras onder ogen komen.$B$BBreng de staf naar Stratholme. Daar vind je een stuk gewijde grond: de plek waar de grootste ridders van Lordaeron zijn vermoord. Leg de bezoedelde staf op de heilige grond en bereid je voor: een wezen met enorme kracht zal van binnenuit losbreken... Versla het demonische wezen dat de staf beheerst en kom terug naar mij.",
  o = "Anachronos bij de Caverns of Time in Tanaris wil dat je Atiesh, Greatstaff of the Guardian naar Stratholme brengt en hem gebruikt op Consecrated Earth. Versla het wezen dat uit de staf wordt verdreven en ga terug naar hem.",
  o1 = "Atiesh gereinigd",
  g = { {"zowel", "both"}, {"bevochten", "fought (bevechten)"}, {"verslagen", "defeated (verslaan)"}, {"onder ogen komen", "to face"}, {"staf", "staff"}, {"gewijde", "consecrated (gewijd)"}, {"ridders", "knights (ridder)"}, {"vermoord", "murdered (vermoorden)"}, {"bezoedelde", "befouled, defiled (bezoedeld)"}, {"heilige", "holy (heilig)"}, {"bereid je voor", "prepare yourself (zich voorbereiden)"}, {"wezen", "being, creature"}, {"losbreken", "to break loose"}, {"beheerst", "controls (beheersen)"}, {"verdreven", "driven out, exorcised (verdrijven)"} },
},

