[9292] = { en = "Cracked Necrotic Crystal", tier = 4,
  t = "Cracked Necrotic Crystal",
  d = "Op het lijk van de verslagen gruwel vind je een gebarsten kristal. Het pulseert langzaam met necrotische energie.",
  o = "Breng het Cracked Necrotic Crystal naar Lieutenant Orrin buiten de poorten van Stormwind.",
  p = "Heb je iets nodig?",
  c = "Hm, heb je dit van het lijk van een van de binnenvallende gruwels gehaald?$b$bWe hebben bericht gekregen over de basiskampen van de necropolissen die de Scourge oproept. Ik vermoed dat ze er een in Stormwind wilden maken. Het is goed dat het ze niet gelukt is.",
  g = { {"lijk", "corpse"}, {"verslagen", "defeated (verslaan)"}, {"gruwel", "abomination"}, {"gebarsten", "cracked (barsten)"}, {"pulseert", "pulses (pulseren)"}, {"necrotische", "necrotic (necrotisch)"}, {"poorten", "gates (poort)"}, {"binnenvallende", "invading (binnenvallen)"}, {"basiskampen", "base camps (basiskamp)"}, {"necropolissen", "necropolises (necropolis)"}, {"oproept", "summons (oproepen)"}, {"vermoed", "suspect (vermoeden)"}, {"gelukt", "succeeded (lukken)"} },
},

[9295] = { en = "Letter from the Front", tier = 4,
  t = "Brief van het front",
  d = "Je hebt deze brief gevonden bij een van de vele dienaren van de Scourge die je hebt gedood. Aan het uiterlijk en de geur te merken is hij al een tijd bij de ondoden geweest. Misschien wil iemand in Light's Hope Chapel hem graag beter bekijken...",
  o = "Breng de Torn Letter naar de Keeper of the Rolls in Light's Hope Chapel in de Eastern Plaguelands.",
  p = "Ja? Wat heb je daar?",
  c = "Wat tragisch. Deze woorden waren duidelijk bedoeld voor iemand van wie de soldaat hield, maar ze zijn nooit aangekomen. Wat hij beschrijft, is jaren geleden gebeurd. Ik weet niet zeker of de persoon voor wie de brief bedoeld was nog leeft.$b$bToch is er nog hoop. Met de namen en de informatie die hij geeft, kan ik de familie misschien vinden! Het kost wat onderzoek, maar de bibliothecaris in Stormwind is me nog een gunst schuldig...$b$bBedankt dat je dit bij me hebt gebracht. Met jouw hulp kunnen we iemand misschien eindelijk gemoedsrust geven.",
  g = { {"dienaren", "minions, servants (dienaar)"}, {"uiterlijk", "appearance"}, {"geur", "smell"}, {"te merken", "judging by (merken)"}, {"ondoden", "undead (ondode)"}, {"bekijken", "to examine, look at"}, {"tragisch", "tragic"}, {"bedoeld", "meant (bedoelen)"}, {"beschrijft", "describes (beschrijven)"}, {"onderzoek", "research"}, {"bibliothecaris", "librarian"}, {"gunst", "favour"}, {"schuldig", "owing, indebted"}, {"eindelijk", "at last"}, {"gemoedsrust", "peace of mind"} },
},

[9299] = { en = "Note from the Front", tier = 4,
  t = "Briefje van het front",
  d = "Je hebt deze brief gevonden bij een van de vele dienaren van de Scourge die je hebt gedood. Aan het uiterlijk en de geur te merken is hij al een tijd bij de ondoden geweest. Misschien wil iemand in Light's Hope Chapel hem graag beter bekijken...",
  o = "Breng de Careworn Note naar de Keeper of the Rolls in Light's Hope Chapel in de Eastern Plaguelands.",
  p = "Ja? Wat heb je daar?",
